RSpec.describe Timekeeping::ServiceToken do
  describe "minting a detach-entries service token" do
    it "gives every token its own jti and a lifetime of exactly the TTL" do
      now = Time.zone.parse("2026-03-01 10:00:00")
      first = described_class.mint(company_id: 7, operations: [described_class::DETACH_ENTRIES],
                                   private_key: timekeeping_key_pair, now:)
      second = described_class.mint(company_id: 7, operations: [described_class::DETACH_ENTRIES],
                                    private_key: timekeeping_key_pair, now:)

      first_claims, = JWT.decode(first, nil, false)
      second_claims, = JWT.decode(second, nil, false)

      expect(first_claims["jti"]).not_to eq(second_claims["jti"])
      expect(first_claims["exp"]).to eq(first_claims["iat"] + 60)
    end

    it "raises MissingKeyError when TIMEKEEPING_TOKEN_PRIVATE_KEY is not set" do
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil) do
        expect { described_class.mint(company_id: 7, operations: [described_class::DETACH_ENTRIES]) }
          .to raise_error(Timekeeping::UserToken::MissingKeyError)
      end
    end
  end

  describe "verifying a service token" do
    it "refuses an expired token" do
      expired = described_class.mint(company_id: 7, operations: [described_class::DETACH_ENTRIES],
                                     private_key: timekeeping_key_pair, now: 2.minutes.ago)

      expect { described_class.verify(expired, public_key: timekeeping_key_pair.public_key) }
        .to raise_error(described_class::InvalidTokenError)
    end

    it "refuses a token whose typ is not timekeeping_service" do
      now = Time.current.to_i
      user_typed = JWT.encode({ sub: "1", company_id: 7, operations: [described_class::DETACH_ENTRIES], iat: now,
                                exp: now + 60, jti: SecureRandom.uuid, typ: "user" }, timekeeping_key_pair, "RS256")

      expect { described_class.verify(user_typed, public_key: timekeeping_key_pair.public_key) }
        .to raise_error(described_class::InvalidTokenError)
    end

    it "returns the company and operations that a genuine token names" do
      token = described_class.mint(company_id: 7, operations: [described_class::DETACH_ENTRIES],
                                   private_key: timekeeping_key_pair)

      claims = described_class.verify(token, public_key: timekeeping_key_pair.public_key)

      expect(claims.company_id).to eq(7)
      expect(claims.operations).to eq(["agents.detach_entries"])
    end
  end
end
